  sum by (container) (
    rate(container_cpu_usage_seconds_total{namespace=~"${namespace:raw}", cluster=~"${cluster:raw}", pod=~"${pod_name:raw}", node=~"${node_name:raw}", image!="", pod=~"${pod_name:raw}", container!="POD", container!="", container=~"${container_name:raw}"}[5m])
  ) > 0.5
) 
/
(
  sum by (container) (
    cluster:namespace:pod_cpu:active:kube_pod_container_resource_requests{namespace=~"${namespace:raw}", cluster=~"${cluster:raw}", pod=~"${pod_name:raw}.*", node=~"${node_name:raw}", container!="POD", container!="", container=~"${container_name:raw}"}
  )
) > 1
